import{_ as d,o as e,c as a,a2 as r}from"./chunks/framework.Bg-Zxr5O.js";const E=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/SPLIT-FILE.md","filePath":"manual-zh/SPLIT-FILE.md","lastUpdated":1785684581000}'),o={name:"manual-zh/SPLIT-FILE.md"};function s(i,t,n,l,c,p){return e(),a("div",null,[...t[0]||(t[0]=[r(`<h3 id="_13-5-split-file" tabindex="-1">13.5 SPLIT FILE <a class="header-anchor" href="#_13-5-split-file" aria-label="Permalink to &quot;13.5 SPLIT FILE&quot;">​</a></h3><pre><code>SPLIT FILE [{LAYERED, SEPARATE}] BY var_list.
SPLIT FILE OFF.
</code></pre><p><code>SPLIT FILE</code> 允许使用单条统计过程命令，将存在于一个数据文件中的多组数据分别进行分析。</p><p>指定一个变量名列表，以分别分析多组数据。这些变量取值相同的相邻个案组成一个组，由统计过程命令作为一个组进行分析。对每一组个案执行独立的分析，并将该组的变量取值随分析结果一同打印。</p><p>当指定变量名列表时，也可以指定关键字 <code>LAYERED</code> 或 <code>SEPARATE</code> 之一。默认的 <code>LAYERED</code> 将每组的独立分析合并呈现在一个表格中。<code>SEPARATE</code> 则将每次分析呈现在单独的表格中。并非所有过程都遵循这一区分。</p><p>分组仅由<em>相邻</em>个案构成。若要使用某个取值在工作文件中不相邻的变量进行拆分，首先按该变量对数据排序（参见 <a href="./SORT-CASES">SORT CASES</a>）。</p><p>指定 <code>OFF</code> 可禁用 <code>SPLIT FILE</code>，并恢复将整个活动数据集作为一个数据组进行分析。</p><p>当 <code>SPLIT FILE</code> 出现在 <code>TEMPORARY</code> 之后时，它只影响下一个过程（参见 <a href="./TEMPORARY">TEMPORARY</a>）。</p><h4 id="_13-5-1-示例-拆分" tabindex="-1">13.5.1 示例 拆分 <a class="header-anchor" href="#_13-5-1-示例-拆分" aria-label="Permalink to &quot;13.5.1 示例 拆分&quot;">​</a></h4><p>文件 horticulture.sav 包含描述若干园艺标本在经受各种 <strong>treatment</strong>（处理）后的 <strong>yield</strong>（产量）数据。如果我们想考察产量的线性统计量，一种方法是使用 <code>DESCRIPTIVES</code>（参见 <a href="./DESCRIPTIVES">DESCRIPTIVES</a>）。不过，不同 <strong>treatment</strong> 的均值理应有所不同。因此我们可能想执行三次独立的过程——每种处理各一次。示例 13.2 展示了如何使用 <code>SPLIT FILE</code> 命令自动完成这一点。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>get file=&#39;horticulture.sav&#39;.  * Ensure cases are sorted before splitting. sort cases by treatment.  split file by treatment.  * Run descriptives on the yield variable descriptives /variable = yield.</span></span></code></pre></div><p><strong>示例 13.2：</strong> 对 <strong>treatment</strong> 的每个取值运行 <code>DESCRIPTIVES</code></p><p>在示例 13.3 中可以看到，描述统计表出现了 3 次——<strong>treatment</strong> 的每个取值各一次。本例中 ‘N’（观测数）在所有拆分中相同。这是因为该实验特意如此设计。但一般来说，每次拆分的 ‘N’ 可以不同。</p><table tabindex="0"><thead><tr><th></th><th>N</th><th>均值</th><th>标准差</th><th>最小值</th><th>最大值</th></tr></thead><tbody><tr><td>Variable</td><td>Value</td><td></td><td></td><td></td><td></td></tr><tr><td>treatment</td><td>control</td><td></td><td></td><td></td><td></td></tr><tr><td>yield</td><td>30</td><td>51.23</td><td>8.28</td><td>37.86</td><td>68.59</td></tr><tr><td>Valid N (listwise)</td><td>30</td><td></td><td></td><td></td><td></td></tr><tr><td>Missing N (listwise)</td><td>0</td><td></td><td></td><td></td><td></td></tr><tr><td>Variable</td><td>Value</td><td></td><td></td><td></td><td></td></tr><tr><td>treatment</td><td>conventional</td><td></td><td></td><td></td><td></td></tr><tr><td></td><td>N</td><td>Mean</td><td>Std Dev</td><td>Minimum</td><td>Maximum</td></tr><tr><td>yield</td><td>30</td><td>53.57</td><td>8.92</td><td>36.30</td><td>70.66</td></tr><tr><td>Valid N (listwise)</td><td>30</td><td></td><td></td><td></td><td></td></tr><tr><td>Missing N (listwise)</td><td>0</td><td></td><td></td><td></td><td></td></tr><tr><td>Variable</td><td>Value</td><td></td><td></td><td></td><td></td></tr><tr><td>treatment</td><td>traditional</td><td></td><td></td><td></td><td></td></tr><tr><td></td><td>N</td><td>Mean</td><td>Std Dev</td><td>Minimum</td><td>Maximum</td></tr><tr><td>yield</td><td>30</td><td>56.87</td><td>8.88</td><td>39.08</td><td>75.93</td></tr><tr><td>Valid N (listwise)</td><td>30</td><td></td><td></td><td></td><td></td></tr><tr><td>Missing N (listwise)</td><td>0</td><td></td><td></td><td></td><td></td></tr></tbody></table><p><strong>示例 13.3：</strong> 在活动拆分状态下运行 <code>DESCRIPTIVES</code> 的结果</p><p>除非使用了 <code>TEMPORARY</code>，否则一旦为数据集定义了拆分，它会一直保持活动状态，直到被显式禁用。在图形用户界面中，活动拆分变量（如果有）显示在状态栏中（参见截图 13.1）。如果在拆分处于活动状态时将数据集保存到系统文件（参见 <a href="./SAVE">SAVE</a>），拆分状态会存储在文件中，并在加载该文件时自动载入。</p><p><strong>截图 13.1：</strong> 指示数据集正使用 <strong>treatment</strong> 变量进行拆分的状态栏</p><h4 id="脚注" tabindex="-1">脚注 <a class="header-anchor" href="#脚注" aria-label="Permalink to &quot;脚注&quot;">​</a></h4><h5 id="_5" tabindex="-1">(5) <a class="header-anchor" href="#_5" aria-label="Permalink to &quot;(5)&quot;">​</a></h5><p>还有其他可能更好的方法，可使用 <code>MEANS</code> 或 <code>EXAMINE</code> 命令达到类似结果。</p>`,20)])])}const S=d(o,[["render",s]]);export{E as __pageData,S as default};
